import{_ as e,a as s,b as t,c as l,d as r,e as n,f as i}from"./chunks/4_cache_20200205144254.BuTohwNa.js";import{_ as o,o as p,c,a0 as d}from"./chunks/framework.DqMqoJl9.js";const q=JSON.parse('{"title":"浏览器缓存(http 缓存)","description":"","frontmatter":{},"headers":[],"relativePath":"performance/7-cache.md","filePath":"performance/7-cache.md","lastUpdated":1791573371000}'),h={name:"performance/7-cache.md"};function f(u,a,m,_,b,y){return p(),c("div",null,[...a[0]||(a[0]=[d('<h1 id="浏览器缓存-http-缓存" tabindex="-1">浏览器缓存(http 缓存) <a class="header-anchor" href="#浏览器缓存-http-缓存" aria-label="Permalink to &quot;浏览器缓存(http 缓存)&quot;">​</a></h1><p>浏览器缓存其实就是浏览器保存通过 HTTP 获取的所有资源,是浏览器将网络资源存储在本地的一种行为。</p><p><img src="'+e+'" alt=""></p><h2 id="_1-缓存存储的位置" tabindex="-1">1 缓存存储的位置 <a class="header-anchor" href="#_1-缓存存储的位置" aria-label="Permalink to &quot;1 缓存存储的位置&quot;">​</a></h2><ul><li>memory cache 将资源缓存到内存中，等待下次访问时不需要重新下载资源，而直接从内存中获取</li><li>disk cache 将资源缓存到磁盘中，等待下次访问时不需要重新下载资源，而直接从磁盘中获取</li></ul><table tabindex="0"><thead><tr><th>-</th><th>memory cache</th><th>disk cache</th></tr></thead><tbody><tr><td>相同点</td><td>只能存储一些派生类资源文件</td><td>只能存储一些派生类资源文件</td></tr><tr><td>不同点</td><td>退出进程时数据会被清除</td><td>退出进程时数据不会被清除</td></tr><tr><td>存储资源</td><td>一般脚本、字体、图片会存在内存当中</td><td>一般非脚本会存在内存当中，如 css 等</td></tr></tbody></table><blockquote><p>因为 CSS 文件加载一次就可渲染出来,我们不会频繁读取它,所以它不适合缓存到内存中,但是 js 之类的脚本却随时可能会执行,如果脚本在磁盘当中,我们在执行脚本的时候需要从磁盘取到内存中来,这样 IO 开销就很大了,有可能导致浏览器失去响应。</p></blockquote><p><strong>三级缓存原理 (访问缓存优先级)</strong></p><ul><li>先在内存中查找,如果有,直接加载</li><li>如果内存中不存在,则在硬盘中查找,如果有直接加载</li><li>如果硬盘中也没有,那么就进行网络请求</li><li>请求获取的资源缓存到硬盘和内存</li></ul><h2 id="_2-缓存类型" tabindex="-1">2 缓存类型 <a class="header-anchor" href="#_2-缓存类型" aria-label="Permalink to &quot;2 缓存类型&quot;">​</a></h2><p>强缓存：</p><ul><li>Expires，是  http1.0  时的规范，它的值为一个绝对时间的 GMT 格式的时间字符串，表示资源的失效时间</li><li>Cache-Control， http1.1  时出现的 header 信息，主要是利用该字段的  max-age  值来进行判断，它是一个相对时间</li></ul><p>协商缓存：</p><ul><li>Last-Modify/If-Modify-Since，是一个时间标识该资源的最后修改时间，当浏览器再次请求该资源时，request 的请求头中会包含 If-Modify-Since，该值为缓存之前返回的 Last-Modify</li><li>ETag/If-None-Match，返回的是一个校验码，资源变化都会导致 ETag 变化，服务器根据 If-None-Match 值来判断是否命中缓存</li></ul><h2 id="_3-强缓存" tabindex="-1">3 强缓存 <a class="header-anchor" href="#_3-强缓存" aria-label="Permalink to &quot;3 强缓存&quot;">​</a></h2><p>浏览器在加载资源时，会先根据本地缓存资源的 header 中的信息判断是否命中强缓存，如果命中则直接使用缓存中的资源不会再向服务器发送请求</p><h3 id="_3-1-expires" tabindex="-1">3.1 Expires <a class="header-anchor" href="#_3-1-expires" aria-label="Permalink to &quot;3.1 Expires&quot;">​</a></h3><p>该字段是 http1.0 时的规范，它的值为一个绝对时间的 GMT 格式的时间字符串，这个时间代表着这个资源的失效时间，在此时间之前，即命中缓存</p><p><img src="'+s+'" alt=""></p><p>缺点：</p><blockquote><p>由于失效时间是一个绝对时间，所以当服务器与客户端时间偏差较大时，就会导致缓存混乱</p></blockquote><h3 id="_3-2-cache-control" tabindex="-1">3.2 Cache-Control <a class="header-anchor" href="#_3-2-cache-control" aria-label="Permalink to &quot;3.2 Cache-Control&quot;">​</a></h3><p>Cache-Control 是 http1.1 时出现的 header 信息，主要是利用该字段的 max-age 值来进行判断，它是一个相对时间，例如 Cache-Control:max-age=3600，代表着资源的有效期是 3600 秒</p><p><img src="'+t+'" alt=""></p><p><strong>常用值：</strong></p><ul><li>no-cache：需要进行协商缓存，发送请求到服务器确认是否使用缓存</li><li>no-store：禁止使用缓存，每一次都要重新请求数据</li><li>public：可以被所有的用户缓存，包括终端用户和 CDN 等中间代理服务器</li><li>private：只能被终端用户的浏览器缓存，不允许 CDN 等中继缓存服务器对其缓存</li><li>Cache-Control 与 Expires 可以在服务端配置同时启用，同时启用的时候 Cache-Control 优先级高</li></ul><h2 id="_4-协商缓存" tabindex="-1">4 协商缓存 <a class="header-anchor" href="#_4-协商缓存" aria-label="Permalink to &quot;4 协商缓存&quot;">​</a></h2><p>当强缓存没有命中的时候，浏览器会发送一个请求到服务器，服务器根据 header 中的部分信息来判断是否命中缓存。如果命中，则返回 304 ，告诉浏览器资源未更新，可使用本地的缓存</p><h3 id="_4-1-last-modify-if-modify-since" tabindex="-1">4.1 Last-Modify/If-Modify-Since <a class="header-anchor" href="#_4-1-last-modify-if-modify-since" aria-label="Permalink to &quot;4.1 Last-Modify/If-Modify-Since&quot;">​</a></h3><p>浏览器第一次请求一个资源的时候，服务器返回的 header 中会加上 Last-Modify，Last-modify 是一个时间标识该资源的最后修改时间</p><p>当浏览器再次请求该资源时，request 的请求头中会包含 If-Modify-Since，该值为缓存之前返回的 Last-Modify。服务器收到 If-Modify-Since 后，根据资源的最后修改时间判断是否命中缓存</p><p>如果命中缓存，则返回 304，并且不会返回资源内容，并且不会返回 Last-Modify</p><p><img src="'+l+'" alt=""> (response header) <img src="'+r+'" alt=""> (request header)</p><p><strong>缺点：</strong></p><ul><li>短时间内资源发生了改变，Last-Modified 并不会发生变化</li><li>如果这个资源在一个周期内修改回原来的样子了，我们认为是可以使用缓存的，但是 Last-Modified 会改变</li></ul><p>参考文档：</p><p><a href="https://juejin.im/post/5c4528a6f265da611a4822cc#heading-12" target="_blank" rel="noreferrer">https://juejin.im/post/5c4528a6f265da611a4822cc#heading-12</a></p><h3 id="_4-2-etag-if-none-match" tabindex="-1">4.2 ETag/If-None-Match <a class="header-anchor" href="#_4-2-etag-if-none-match" aria-label="Permalink to &quot;4.2 ETag/If-None-Match&quot;">​</a></h3><p>Etag/If-None-Match 返回的是一个校验码。ETag 可以保证每一个资源是唯一的，资源变化都会导致 ETag 变化。服务器根据 If-None-Match 值来判断是否命中缓存。</p><p>Last-Modified 与 ETag 是可以一起使用的，服务器会优先验证 ETag，一致的情况下，才会继续比对 Last-Modified，最后才决定是否返回 304</p><p><img src="'+n+'" alt=""> (response header) <img src="'+i+`" alt=""> (request header)</p><h2 id="_5-注意点" tabindex="-1">5 注意点 <a class="header-anchor" href="#_5-注意点" aria-label="Permalink to &quot;5 注意点&quot;">​</a></h2><ul><li>强缓存和协商缓存都需要服务端返回相应的 response header</li><li>协商缓存需要服务端去对比 requese header 中的 If-Modify-Since/If-None-Match，然后返回资源或 304</li></ul><p>如 express 使用的 <code>server-static</code> 中间件的配置：</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">app.</span><span style="color:#6F42C1;">use</span><span style="color:#24292E;">(</span></span>
<span class="line"><span style="color:#6F42C1;">  serverStatic</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;static&#39;</span><span style="color:#24292E;">, {</span></span>
<span class="line"><span style="color:#24292E;">    etag: </span><span style="color:#005CC5;">true</span><span style="color:#24292E;">,</span></span>
<span class="line"><span style="color:#24292E;">    lastModified: </span><span style="color:#005CC5;">true</span><span style="color:#24292E;">,</span></span>
<span class="line"><span style="color:#24292E;">    maxAge: </span><span style="color:#005CC5;">0</span></span>
<span class="line"><span style="color:#24292E;">  })</span></span>
<span class="line"><span style="color:#24292E;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div>`,45)])])}const M=o(h,[["render",f]]);export{q as __pageData,M as default};
